/* Frozen LE wire bytes from the U1b-0 layout, never generated by a struct.
 * This pins framing only, not producer or transport qualification. */
#include "../src/pgwt_transport_wire.h"
#include "../src/merge_capture.h"
#include <stdio.h>
#include <string.h>

#define CHECK(expr) do { if (!(expr)) { \
    fprintf(stderr, "wire assertion line %d: %s\n", __LINE__, #expr); \
    return 1; } } while (0)

static const struct {
    const char *name;
    unsigned char bytes[32];
    unsigned kind, flags, payload_len, cpu;
    uint64_t seq, cookie, q;
} goldens[] = {
    {"TRACE", {
        0x01,0x00,0x01,0x01,0x30,0x00,0x23,0x01,
        0x08,0x07,0x06,0x05,0x04,0x03,0x02,0x01,
        0x18,0x17,0x16,0x15,0x14,0x13,0x12,0x11,
        0x28,0x27,0x26,0x25,0x24,0x23,0x22,0x21
    }, PGWT_WIRE_TRACE, PGWT_WIRE_HAS_Q, 48, 0x0123,
       UINT64_C(0x0102030405060708), UINT64_C(0x1112131415161718),
       UINT64_C(0x2122232425262728)},
    {"LIFECYCLE", {
        0x01,0x00,0x02,0x00,0x18,0x00,0x34,0x12,
        0x98,0x87,0x76,0x65,0x54,0x43,0x32,0x21,
        0x88,0x77,0x66,0x55,0x44,0x33,0x22,0x11,
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00
    }, PGWT_WIRE_LIFECYCLE, 0, 24, 0x1234,
       UINT64_C(0x2132435465768798), UINT64_C(0x1122334455667788), 0},
    {"TEXT", {
        0x01,0x00,0x03,0x00,0x10,0x01,0xfe,0x00,
        0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00
    }, PGWT_WIRE_TEXT, 0, 272, 254, UINT64_MAX, 0, 0},
    {"BOUNDARY", {
        0x01,0x00,0x04,0x00,0x10,0x00,0x02,0x00,
        0x09,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00
    }, PGWT_WIRE_BOUNDARY, 0, 16, 2, 9, 0, 0},
};

int main(void)
{
    /* These native layouts are the LE producer/reader ABI (Mac and x86
     * Linux). A big-endian port must supply explicit conversion first. */
    const uint16_t endian = 1;
    CHECK(*(const unsigned char *)&endian == 1);
    CHECK(PGWT_WIRE_VERSION == 1);
    CHECK(PGWT_WIRE_DEST_CPU == 0);
    CHECK(PGWT_WIRE_DEST_E == 1);
    CHECK(PGWT_WIRE_DEST_L == 2);
    CHECK(PGWT_WIRE_HAS_Q == 1);
    CHECK(MA_ALLOCATOR == (1U << 0) && MA_FRESH_FORK == (1U << 1));
    CHECK(MA_MATCHING_COOKIE == (1U << 2) && MA_ATTACH_ORDER == (1U << 3));
    CHECK(MA_PRESERVE_STATE == (1U << 4) && MA_SAFE_CLEANUP == (1U << 5));
    CHECK(MA_EMISSION_COOKIE == (1U << 6) && MA_SEQUENCE == (1U << 7));
    CHECK(MA_FAILURE_ACCOUNTING == (1U << 8) && MA_CONTINUOUS == (1U << 9));
    CHECK(MA_FRESH_FIRST == (1U << 10) && MA_IDEMPOTENT_INIT == (1U << 11));
    for (size_t i = 0; i < sizeof(goldens) / sizeof(goldens[0]); ++i) {
        struct pgwt_wire_hdr hdr;
        memcpy(&hdr, goldens[i].bytes, sizeof(hdr));
        CHECK(hdr.version == 1);
        CHECK(hdr.kind == goldens[i].kind);
        CHECK(hdr.flags == goldens[i].flags);
        CHECK(hdr.payload_len == goldens[i].payload_len);
        CHECK(hdr.cpu == goldens[i].cpu);
        CHECK(hdr.seq == goldens[i].seq);
        CHECK(hdr.cookie == goldens[i].cookie);
        CHECK(hdr.q == goldens[i].q);
        printf("wire golden %s: PASS\n", goldens[i].name);
    }
    const unsigned char boundary_bytes[16] = {
        0x08,0x07,0x06,0x05,0x04,0x03,0x02,0x01,
        0x44,0x33,0x22,0x11,0x02,0x00,0x00,0x00
    };
    struct pgwt_wire_boundary boundary;
    memcpy(&boundary, boundary_bytes, sizeof(boundary));
    CHECK(boundary.w == UINT64_C(0x0102030405060708));
    CHECK(boundary.round == 0x11223344);
    CHECK(boundary.dest == PGWT_WIRE_DEST_L);
    const unsigned char ctl_bytes[8] = {
        0x88,0x77,0x66,0x55,0x01,0x00,0x00,0x00
    };
    struct pgwt_transport_ctl ctl;
    memcpy(&ctl, ctl_bytes, sizeof(ctl));
    CHECK(ctl.round == 0x55667788 && ctl.el_request == 1);
    puts("wire golden boundary payload/control and MA bit order: PASS");
    return 0;
}
